---

Restore the missing line. Match the surrounding behavior; equivalent working code is fine.

```js
const deserializeRow = (row, delimiter = ',') => {
  const values = [];
  ____
  while (true) {
    if (index === row.length) {
      values.push(row.slice(matchStart, index));
      break;
    }
    const char = row[index];
    if (char === delimiter && !isInsideQuotations) {
      values.push(
        row
          .slice(matchStart, index)
          .replace(/^"|"$/g, '')
          .replace(/""/g, '"')
          .replace(/\\n/g, '\n')
